export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.setHeader('Cache-Control', 'no-store');
  if (req.method === 'OPTIONS') { res.status(204).end(); return; }
  const allowLive = (req.headers['x-arl-live'] === '1') || (req.headers.host && req.headers.host.indexOf('localhost') === 0);
  if (allowLive) {
    try {
      const sql = (await import('mssql')).default;
      const pool = await sql.connect({
        user: process.env.MSSQL_USER || 'mcp_user',
        password: process.env.MSSQL_PASSWORD,
        server: process.env.MSSQL_SERVER || '203.202.241.211',
        port: parseInt(process.env.MSSQL_PORT || '1433', 10),
        database: process.env.MSSQL_DATABASE || 'DWH',
        options: { encrypt: false, trustServerCertificate: true },
        requestTimeout: 6000, connectionTimeout: 3000
      });
      const q = await pool.request().query(`SELECT TOP 6000 CONVERT(varchar(10), h.dteTransactionDate, 23) AS dte, h.strBusinessUnitName AS sbu,
        ISNULL(h.strPlantName,'') AS plant, ISNULL(h.strWarehouseName,'') AS wh,
        ROUND(SUM(CASE WHEN h.TransactionGroupName IN ('Receive Inventory','Received From Production','Service Receive','Asset Receive','Transfer In','Received From Customer','Issue Return') THEN r.numTransactionQuantity ELSE 0 END),2) AS r,
        ROUND(SUM(CASE WHEN h.TransactionGroupName IN ('Issue Inventory','Transfer Out','Purchase Return') THEN ABS(r.numTransactionQuantity) ELSE 0 END),2) AS i,
        ROUND(SUM(r.numTransactionQuantity),2) AS n
        FROM wms.tblInventoryTransactionHeaderArc h
        JOIN wms.tblInventoryTransactionRowArc r ON h.intInventoryTransactionId = r.intInventoryTransactionId
        WHERE h.isActive=1 AND r.isActive=1 AND h.strBusinessUnitName NOT LIKE '%Demo%' AND h.strBusinessUnitName IS NOT NULL
          AND h.dteTransactionDate >= DATEADD(day,-60,GETDATE())
        GROUP BY CONVERT(varchar(10), h.dteTransactionDate, 23), h.strBusinessUnitName, h.strPlantName, h.strWarehouseName
        ORDER BY SUM(ABS(r.numTransactionQuantity)) DESC`);
      await pool.close();
      res.status(200).json({ rows: q.recordset, source: 'live', count: q.recordset.length });
      return;
    } catch (e) { console.error('movement live error:', e.message); }
  }
  res.status(200).json({ rows: FALLBACK, source: 'snapshot', count: FALLBACK.length });
}
